namespace nova64 { static bool match(const TlbEntry&e,uint32_t va,uint32_t hi){uint32_t mask=e.page_mask|0x1fff;return (va&~mask)==(e.entry_hi&~mask)&&((e.entry_hi^hi)&0xff)==0;} Translation Tlb::translate(uint32_t va,bool wr,uint32_t hi)const{for(auto&e:e_)if(match(e,va,hi)){bool odd=((va>>(12+((e.page_mask>>13)&0xff)))&1);uint32_t lo=odd?e.lo1:e.lo0;if(!(lo&2))throw std::runtime_error("TLB invalid");if(wr&&!(lo&4))throw std::runtime_error("TLB modified");uint32_t off=va&(0xfff|e.page_mask);return {(lo>>6)<<12 | off,(lo&4)!=0};}throw std::runtime_error("TLB refill");} int Tlb::probe(uint32_t hi)const{for(unsigned i=0;i<32;i++)if((e_[i].entry_hi&0xff)==(hi&0xff)&&((e_[i].entry_hi^hi)&~0xffu)==0)return i;return -1;} unsigned Tlb::random(uint32_t wired)const{return wired+(31-wired)%((32-wired)?(32-wired):1);}}
